<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/bootstrap.php';
require_method('DELETE');
$user=current_user();require_csrf();rate_limit('purge_bounced_leads',$user['tenant_id'].':'.$user['id'],10,3600);$data=input();
$scope=strtoupper((string)($data['scope']??'SELECTED'));$ids=array_values(array_unique(array_filter(array_map('strval',(array)($data['ids']??[])))));if($scope!=='ALL_BOUNCED'&&(!$ids||count($ids)>5000))throw new ApiError(422,'Select between 1 and 5,000 bounced leads.');
$where="tenant_id=? AND status='BOUNCED'";$params=[$user['tenant_id']];if($scope!=='ALL_BOUNCED'){$where.=' AND public_id IN ('.implode(',',array_fill(0,count($ids),'?')).')';array_push($params,...$ids);}if($user['role']==='MEMBER'){$where.=' AND (assigned_user_id=? OR created_by=?)';array_push($params,$user['id'],$user['id']);}
$pdo=db();$pdo->beginTransaction();try{$find=$pdo->prepare("SELECT id FROM leads WHERE {$where} LIMIT 5000 FOR UPDATE");$find->execute($params);$leadIds=array_map('intval',$find->fetchAll(PDO::FETCH_COLUMN));if(!$leadIds){$pdo->commit();respond(['deleted'=>0]);}$marks=implode(',',array_fill(0,count($leadIds),'?'));$campaigns=$pdo->prepare("SELECT DISTINCT campaign_id FROM campaign_recipients WHERE tenant_id=? AND lead_id IN ({$marks})");$campaigns->execute([$user['tenant_id'],...$leadIds]);$campaignIds=array_map('intval',$campaigns->fetchAll(PDO::FETCH_COLUMN));$pdo->prepare("DELETE FROM campaign_recipients WHERE tenant_id=? AND lead_id IN ({$marks})")->execute([$user['tenant_id'],...$leadIds]);$delete=$pdo->prepare("DELETE FROM leads WHERE tenant_id=? AND id IN ({$marks}) AND status='BOUNCED'");$delete->execute([$user['tenant_id'],...$leadIds]);foreach($campaignIds as $campaignId){$stats=$pdo->prepare("SELECT COUNT(*) total,COALESCE(SUM(status='SENT'),0) sent,COALESCE(SUM(status='FAILED'),0) failed,COALESCE(SUM(status IN ('PENDING','PROCESSING','RETRY')),0) pending FROM campaign_recipients WHERE tenant_id=? AND campaign_id=?");$stats->execute([$user['tenant_id'],$campaignId]);$counts=$stats->fetch();$pdo->prepare("UPDATE campaigns SET total_recipients=?,sent_count=?,failed_count=?,pending_count=?,status=CASE WHEN ?=0 AND status IN ('QUEUED','RUNNING','PAUSED') THEN IF(?=0,'CANCELLED',IF(?=0 AND ?>0,'FAILED','COMPLETED')) ELSE status END,completed_at=CASE WHEN ?=0 THEN COALESCE(completed_at,UTC_TIMESTAMP()) ELSE NULL END WHERE tenant_id=? AND id=?")->execute([(int)$counts['total'],(int)$counts['sent'],(int)$counts['failed'],(int)$counts['pending'],(int)$counts['pending'],(int)$counts['total'],(int)$counts['sent'],(int)$counts['failed'],(int)$counts['pending'],$user['tenant_id'],$campaignId]);}$pdo->commit();audit('lead.bounced_purged','lead',null,['count'=>$delete->rowCount(),'scope'=>$scope]);respond(['deleted'=>$delete->rowCount()]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
